using STOREEX.Models; using System; using System.Linq; using System.Web.Mvc;
namespace STOREEX.Controllers { [Authorize] public class DashboardController:Controller { private readonly StoreexDb db=new StoreexDb(); private const int CompanyId=1; public ActionResult Index(){var t=DateTime.Today;var m=new DateTime(t.Year,t.Month,1);ViewBag.SalesToday=db.Invoices.Where(x=>x.CompanyId==CompanyId&&x.Status!=InvoiceStatus.Cancelled&&x.InvoiceDate>=t).Select(x=>(decimal?)x.Total).Sum()??0;ViewBag.SalesMonth=db.Invoices.Where(x=>x.CompanyId==CompanyId&&x.Status!=InvoiceStatus.Cancelled&&x.InvoiceDate>=m).Select(x=>(decimal?)x.Total).Sum()??0;ViewBag.Customers=db.Customers.Count(x=>x.CompanyId==CompanyId&&x.IsActive);ViewBag.Products=db.Products.Count(x=>x.CompanyId==CompanyId&&x.IsActive);ViewBag.Warehouses=db.Warehouses.Count(x=>x.CompanyId==CompanyId&&x.IsActive);ViewBag.LowStock=db.WarehouseStocks.Count(x=>x.Product.CompanyId==CompanyId&&x.Quantity<=x.Product.MinimumStock);ViewBag.Receivables=db.Invoices.Where(x=>x.CompanyId==CompanyId).Select(x=>(decimal?)x.Balance).Sum()??0;return View();} public JsonResult MonthlySales(){var from=DateTime.Today.AddMonths(-11);var d=db.Invoices.Where(x=>x.CompanyId==CompanyId&&x.InvoiceDate>=from&&x.Status!=InvoiceStatus.Cancelled).GroupBy(x=>new{x.InvoiceDate.Year,x.InvoiceDate.Month}).Select(g=>new{g.Key.Year,g.Key.Month,Total=g.Sum(x=>x.Total)}).OrderBy(x=>x.Year).ThenBy(x=>x.Month);return Json(d,JsonRequestBehavior.AllowGet);} protected override void Dispose(bool d){if(d)db.Dispose();base.Dispose(d);}}}